// Luma MVP - autogenerated by Cursor
import SwiftUI
import WebKit
import AppKit
import Combine
import UniformTypeIdentifiers

/// Holds address bar suggestion selection for keyboard (Up/Down/Enter) and autofill.
private final class AddressBarKeyState: ObservableObject {
    @Published var selectedIndex: Int = 0
    @Published var totalCount: Int = 0
    @Published var visible: Bool = false
    @Published var submitSelection: Bool = false
}

/// Minimal browser shell hosting WKWebViews via WebViewWrapper and TabManager.
///
/// Per SRS: WebKit-only renderer, minimal tab UI, address bar.
/// Omnibox: accepts full URL, domain, or search query.
/// Per SECURITY.md: No JS message handlers, no HTML scraping.
struct BrowserShellView: View {
    // MARK: - Profile state
    @ObservedObject private var profileManager = ProfileManager.shared
    @AppStorage("luma_search_suggestions_enabled") private var searchSuggestionsEnabled: Bool = false
    @StateObject private var sessionStore: BrowserSessionStore

    private var session: ProfileSession { sessionStore.activeSession }
    private var tabManager: TabManager { session.tabManager }
    private var web: WebViewWrapper { session.webViewWrapper }
    private var historyManager: HistoryManager { session.historyManager }
    private var activeProfile: BrowserProfile { profileManager.profile(for: sessionStore.activeProfileId) }

    init(initialProfileId: UUID? = nil) {
        _sessionStore = StateObject(wrappedValue: BrowserSessionStore(initialProfileId: initialProfileId))
    }

    @State private var addressBarText: String = ""
    @State private var tabsWithPanelOpen: Set<UUID> = []
    @State private var aiPanelWidth: CGFloat = 380
    @State private var shouldResetPanelWidth: Bool = false
    @State private var isDraggingDivider: Bool = false
    @State private var eventMonitor: Any?
    @State private var scrollMonitor: Any?
    /// Horizontal trackpad travel over the chrome in the current gesture (profile swipe).
    @State private var swipeTravel: CGFloat = 0
    @State private var swipeConsumed = false
    /// Brief name badge after switching profiles.
    @State private var profileToast: BrowserProfile?
    @State private var pendingAction: BrowserAction? = nil
    @State private var pendingAssistantText: String = ""
    @State private var showActionConfirm: Bool = false
    @State private var restoreAddressBarOnEscape: Bool = false
    @State private var isFirstLoad: Bool = true
    @FocusState private var addressBarFocused: Bool
    @State private var searchSuggestions: [String] = []
    @State private var historySuggestions: [(display: String, url: URL)] = []
    @StateObject private var addressBarKeyState = AddressBarKeyState()
    @State private var suggestionDebounceTask: DispatchWorkItem?
    @State private var historyDebounceTask: DispatchWorkItem?
    @State private var showDownloadsHub: Bool = false
    @State private var showGoogleAPIKeyHelpSheet: Bool = false
    @State private var showBrowserFindBar: Bool = false
    @State private var browserFindQuery: String = ""
    /// Luna Max "Ask on Page" card for the current tab.
    @State private var askOnPageVisible: Bool = false
    @ObservedObject private var downloadManager = DownloadManager.shared
    @State private var downloadIconScale: CGFloat = 1
    @State private var isFullScreen: Bool = false
    @State private var hostWindow: NSWindow?

    // Layout
    @AppStorage(BrowserLayout.defaultsKey) private var layoutRaw: String = BrowserLayout.sidebar.rawValue
    @AppStorage("luna_sidebar_visible") private var sidebarVisible: Bool = true
    @AppStorage("luna_sidebar_width") private var sidebarWidth: Double = 240
    /// Sidebar temporarily shown over the content while it's hidden (hover at the left edge).
    @State private var sidebarPeeking: Bool = false

    private let router = CommandRouter()
    private let gemini = GeminiClient(apiKeyProvider: { KeychainManager.shared.fetchGeminiKey() })
    private let ollama = OllamaClient()

    // Chrome options (Settings → Appearance)
    @AppStorage(ChromePrefs.frameless) private var frameless = false
    @AppStorage(ChromePrefs.alwaysShowTopBar) private var alwaysShowTopBar = false
    @AppStorage(ChromePrefs.roundedFrame) private var roundedFrame = true
    @AppStorage(ChromePrefs.hideWindowButtons) private var hideWindowButtons = true
    /// Top bar temporarily shown in frameless mode (hover at the top edge, or ⌘L).
    @State private var topBarPeeking = false
    /// Window buttons shown because the pointer is at the top edge (sidebar hidden).
    @State private var windowButtonsPeeking = false

    var body: some View {
        ZStack {
            VisualEffectView(material: usesSidebar ? .sidebar : .titlebar, blendingMode: .behindWindow, state: .followsWindowActiveState)
                .ignoresSafeArea()
            // The window chrome carries a hue of the active profile's color.
            activeProfile.profileColor.color
                .opacity(0.14)
                .ignoresSafeArea()
                .animation(.easeInOut(duration: 0.3), value: activeProfile.colorId)

            TitlebarConfigurator(tabStripHeight: 0, isFullScreen: $isFullScreen, hostWindow: $hostWindow)

            GeometryReader { geometry in
                HStack(spacing: 0) {
                    if sidebarShown {
                        sidebar
                            .frame(width: sidebarWidth)
                            .overlay(alignment: .trailing) { SidebarResizeHandle(width: $sidebarWidth) }
                            .transition(.move(edge: .leading).combined(with: .opacity))
                    }

                    // Main browser content
                    VStack(spacing: 0) {
                        if showsTopChrome {
                            topChrome(showsTabs: !frameless)
                        }
                        framedContent
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .animation(.easeInOut(duration: 0.08), value: tabManager.currentTab)

                    // ─── AI side panel (hidden on start page and AI chat) ────────
                    if let currentId = tabManager.currentTab, tabsWithPanelOpen.contains(currentId), !isCurrentTabStartOrAIChat {
                        HStack(spacing: 0) {
                            PanelResizeHandle(panelWidth: $aiPanelWidth, windowWidth: geometry.size.width, isDragging: $isDraggingDivider)

                            CommandSurfaceView(
                                isPresented: Binding(
                                    get: { tabsWithPanelOpen.contains(currentId) },
                                    set: { if !$0 { tabsWithPanelOpen.remove(currentId) } }
                                ),
                                messages: Binding(
                                    get: { session.chatStore.messages(for: currentId) },
                                    set: { session.chatStore.setMessages($0, for: currentId) }
                                ),
                                webViewWrapper: web,
                                commandRouter: router,
                                gemini: gemini,
                                ollama: ollama,
                                historyManager: historyManager,
                                tabId: currentId
                            ) { response in
                                pendingAssistantText = response.text
                                pendingAction = response.action
                                showActionConfirm = (response.action != nil)
                            }
                            // Floating panel: inset from the window edges; it draws its own glass and shadow.
                            .frame(width: aiPanelWidth - 10)
                            .padding(.trailing, 10)
                            .padding(.vertical, 10)
                        }
                        .transition(.asymmetric(
                            insertion: .move(edge: .trailing).combined(with: .opacity),
                            removal: .move(edge: .trailing).combined(with: .opacity)
                        ))
                        .animation(isDraggingDivider ? nil : .spring(response: 0.35, dampingFraction: 0.85), value: tabsWithPanelOpen.contains(currentId))
                        .animation(isDraggingDivider ? nil : .spring(response: 0.3, dampingFraction: 0.9), value: aiPanelWidth)
                        .onAppear {
                            if shouldResetPanelWidth {
                                // Set to 1/3 of total width
                                aiPanelWidth = geometry.size.width / 3
                                shouldResetPanelWidth = false
                            }
                        }
                    }
                }
            }
        }
        .ignoresSafeArea(.container, edges: .top)
        .overlayPreferenceValue(AddressFieldAnchorKey.self) { anchor in
            suggestionsOverlay(anchor: anchor)
        }
        .overlay(alignment: .leading) {
            if edgeTabListEnabled { sidebarPeekOverlay.ignoresSafeArea(.container, edges: .top) }
        }
        .overlay(alignment: .top) {
            if topBarAutoHides {
                topBarPeekOverlay.ignoresSafeArea(.container, edges: .top)
            } else if trafficLightsHidden || windowButtonsPeeking {
                windowButtonsHotZone.ignoresSafeArea(.container, edges: .top)
            }
        }
        .animation(.spring(response: 0.3, dampingFraction: 0.9), value: sidebarVisible)
        .overlay(alignment: .top) {
            if let profile = profileToast {
                HStack(spacing: 8) {
                    Image(nsImage: ProfileAvatar.image(for: profile, size: 20))
                    Text(profile.name).font(.system(size: 13, weight: .semibold))
                }
                .padding(.horizontal, 14)
                .padding(.vertical, 8)
                .background(Capsule().fill(.regularMaterial))
                .overlay(Capsule().strokeBorder(profile.profileColor.color.opacity(0.5), lineWidth: 1))
                .shadow(color: .black.opacity(0.2), radius: 10, y: 4)
                .padding(.top, 14)
                .transition(.move(edge: .top).combined(with: .opacity))
                .allowsHitTesting(false)
            }
        }
        .focusedSceneValue(\.profileCommands, ProfileCommandContext(
            activeProfileId: sessionStore.activeProfileId,
            switchTo: switchToProfile,
            openInNewWindow: openProfileInNewWindow
        ))
        .alert("Confirm Action", isPresented: $showActionConfirm) {
            Button("Cancel", role: .cancel) { pendingAction = nil }
            Button("Execute") { executePendingAction() }
        } message: {
            if let action = pendingAction {
                let typeText = action.type.rawValue
                let payloadSummary = action.payload?
                    .sorted { $0.key < $1.key }
                    .map { "\($0.key): \($0.value)" }
                    .joined(separator: "\n") ?? "none"
                Text("Assistant: \(pendingAssistantText)\n\nAction: \(typeText)\n\(payloadSummary)")
            } else {
                Text("No action to execute.")
            }
        }
        .sheet(isPresented: $showDownloadsHub) {
            DownloadsHubView()
        }
        .onAppear {
            #if DEBUG
            if ProcessInfo.processInfo.environment["LUNA_SNAPSHOT_AI_PANEL"] != nil {
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { toggleAIPanel() }
            }
            #endif
            web.tabManager = tabManager
            if tabManager.currentTab == nil {
                _ = tabManager.newTab(url: nil)
                if let id = tabManager.currentTab {
                    web.setActiveTab(id)
                    addressBarText = ""
                }
            }
            if scrollMonitor == nil {
                scrollMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { event in
                    handleProfileSwipe(event) ? nil : event
                }
            }
            guard eventMonitor == nil else { return }
            eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                // Only handle shortcuts for this browser window. Prevents double-handling when
                // multiple windows are open, and keeps sheets/settings windows working normally.
                guard let host = hostWindow, event.window === host else { return event }
                let key = event.charactersIgnoringModifiers ?? ""
                if event.modifierFlags.contains(.command) {
                    if key == "e" {
                        DispatchQueue.main.async { toggleAIPanel() }
                        return nil
                    }
                    if key == "s", usesSidebar, !event.modifierFlags.contains(.shift) {
                        DispatchQueue.main.async { toggleSidebar() }
                        return nil
                    }
                    if key == "t" {
                        DispatchQueue.main.async { newTab() }
                        return nil
                    }
                    if key == "w" {
                        DispatchQueue.main.async { closeCurrentTab() }
                        return nil
                    }
                    if key == "y" {
                        DispatchQueue.main.async { navigateToHistory() }
                        return nil
                    }
                    if key == "l" {
                        DispatchQueue.main.async {
                            if usesSidebar && !sidebarShown { sidebarPeeking = true }
                            if topBarAutoHides { topBarPeeking = true }
                            addressBarFocused = true
                        }
                        return nil
                    }
                    // Cmd+R: reload current tab
                    if key == "r" {
                        DispatchQueue.main.async {
                            if let id = tabManager.currentTab { web.reload(in: id) }
                        }
                        return nil
                    }
                    // Cmd+P: print current page
                    if key == "p" {
                        DispatchQueue.main.async {
                            if let id = tabManager.currentTab { web.printPage(in: id) }
                        }
                        return nil
                    }
                    // Cmd+1...9: switch to tab by index
                    if key >= "1", key <= "9", let idx = Int(key), idx >= 1, idx <= 9 {
                        DispatchQueue.main.async {
                            if idx <= tabManager.tabCount() {
                                tabManager.switchToTab(index: idx - 1)
                            }
                        }
                        return nil
                    }
                    // Cmd+= / Cmd+Plus: zoom in
                    if key == "=" || key == "+" {
                        DispatchQueue.main.async { web.zoomIn(tabManager.currentTab) }
                        return nil
                    }
                    // Cmd+-: zoom out
                    if key == "-" {
                        DispatchQueue.main.async { web.zoomOut(tabManager.currentTab) }
                        return nil
                    }
                    // Cmd+0: zoom reset to 100%
                    if key == "0" {
                        DispatchQueue.main.async { web.zoomReset(tabManager.currentTab) }
                        return nil
                    }
                    // Cmd+F: find in page (web tabs only; start page / AI chat handle it themselves)
                    if key == "f" {
                        guard !isCurrentTabStartOrAIChat else { return event }
                        // Luna Max: holding ⌘F (key repeat) or ⌘⇧F opens Ask on Page.
                        if LunaMaxPrefs.isOn(LunaMaxPrefs.askOnPage),
                           event.isARepeat || event.modifierFlags.contains(.shift) {
                            DispatchQueue.main.async { openAskOnPage() }
                            return nil
                        }
                        DispatchQueue.main.async {
                            showBrowserFindBar.toggle()
                            if !showBrowserFindBar {
                                browserFindQuery = ""
                                if let id = tabManager.currentTab {
                                    web.clearFind(in: id)
                                }
                            }
                        }
                        return nil
                    }
                }
                // Address bar suggestions: Down/Up/Enter when dropdown is visible (keyboard selection + autofill)
                if addressBarKeyState.visible {
                    if event.keyCode == 125 { // Down
                        DispatchQueue.main.async {
                            // max(0, …) prevents -1 when suggestions are momentarily empty.
                            addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex + 1, max(0, addressBarKeyState.totalCount - 1))
                        }
                        return nil
                    }
                    if event.keyCode == 126 { // Up
                        DispatchQueue.main.async {
                            addressBarKeyState.selectedIndex = max(0, addressBarKeyState.selectedIndex - 1)
                        }
                        return nil
                    }
                    if event.keyCode == 36 { // Return
                        DispatchQueue.main.async { addressBarKeyState.submitSelection = true }
                        return nil
                    }
                }
                if event.keyCode == 53 { // Escape
                    if showBrowserFindBar {
                        DispatchQueue.main.async {
                            showBrowserFindBar = false
                            browserFindQuery = ""
                            if let id = tabManager.currentTab { web.clearFind(in: id) }
                        }
                        return nil
                    }
                    if addressBarFocused {
                        DispatchQueue.main.async { restoreAddressBarOnEscape = true }
                        return nil
                    }
                    // Let Escape reach web content (exit fullscreen video, close site dialogs, etc).
                    return event
                }
                return event
            }
        }
        .onChange(of: trafficLightsHidden, initial: true) { _, _ in applyTrafficLights() }
        .onChange(of: windowButtonsPeeking) { _, _ in applyTrafficLights() }
        .onChange(of: hostWindow) { _, _ in applyTrafficLights() }
        .onChange(of: tabManager.currentTab) { _, _ in
            askOnPageVisible = false
            web.linkPreview = nil
        }
        .onChange(of: tabManager.currentTab) { _, newId in
            if let id = newId {
                web.setActiveTab(id)
                syncAddressBarFromCurrentTab()
            } else {
                addressBarText = ""
            }
        }
        .onChange(of: web.currentURL) { _, _ in
            syncAddressBarFromCurrentTab()
            if web.currentURL != nil { isFirstLoad = false }
        }
        .onChange(of: profileManager.profiles) { _, profiles in
            let validIds = Set(profiles.map(\.id))
            // Tear down sessions for any deleted profiles, including inactive ones.
            sessionStore.pruneSessions(keeping: validIds)
            guard !validIds.contains(sessionStore.activeProfileId) else { return }
            let deletedId = sessionStore.activeProfileId
            sessionStore.removeSession(profileId: deletedId)
            sessionStore.switchTo(profileId: profileManager.lastActiveProfileId)
            tabsWithPanelOpen = []
            syncAddressBarFromCurrentTab()
        }
        .onChange(of: restoreAddressBarOnEscape) { _, new in
            if new {
                syncAddressBarFromCurrentTab()
                addressBarFocused = false
                restoreAddressBarOnEscape = false
            }
        }
        .onChange(of: addressBarKeyState.selectedIndex) { _, newValue in
            guard addressBarKeyState.visible else { return }
            let h = historySuggestions.count
            let total = h + searchSuggestions.count
            guard newValue >= 0, newValue < total else { return }
            if newValue < h {
                addressBarText = historySuggestions[newValue].url.absoluteString
            } else {
                addressBarText = searchSuggestions[newValue - h]
            }
        }
        .onChange(of: addressBarKeyState.submitSelection) { _, new in
            if new {
                applySelectionAtIndex(addressBarKeyState.selectedIndex)
                addressBarKeyState.submitSelection = false
            }
        }
        .onChange(of: historySuggestions.count) { _, _ in
            if addressBarKeyState.visible {
                addressBarKeyState.totalCount = historySuggestions.count + searchSuggestions.count
                addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex, max(0, addressBarKeyState.totalCount - 1))
            }
        }
        .onChange(of: searchSuggestions.count) { _, _ in
            if addressBarKeyState.visible {
                addressBarKeyState.totalCount = historySuggestions.count + searchSuggestions.count
                addressBarKeyState.selectedIndex = min(addressBarKeyState.selectedIndex, max(0, addressBarKeyState.totalCount - 1))
            }
        }
        .onDisappear {
            sessionStore.flush()
            if let m = eventMonitor {
                NSEvent.removeMonitor(m)
                eventMonitor = nil
            }
            if let m = scrollMonitor {
                NSEvent.removeMonitor(m)
                scrollMonitor = nil
            }
        }
    }

    // MARK: - Layout pieces

    private var layout: BrowserLayout { BrowserLayout(stored: layoutRaw) }
    private var usesSidebar: Bool { layout == .sidebar }
    /// Frameless mode in the sidebar layout means the sidebar auto-hides.
    private var sidebarShown: Bool { usesSidebar && sidebarVisible && !frameless }
    private var showsTopChrome: Bool { !usesSidebar && (!frameless || alwaysShowTopBar) }
    private var topBarAutoHides: Bool { !usesSidebar && frameless && !alwaysShowTopBar }
    /// The left-edge tab list: a hidden sidebar, or the tab list in frameless top layouts.
    /// Window buttons disappear with the chrome they sit on (frameless, hidden sidebar)
    /// and come back while it's revealed.
    private var trafficLightsHidden: Bool {
        guard hideWindowButtons, !isFullScreen else { return false }
        guard !windowButtonsPeeking else { return false }
        return (topBarAutoHides && !topBarPeeking) || (usesSidebar && !sidebarShown && !sidebarPeeking)
    }

    private func applyTrafficLights() {
        guard let window = hostWindow else { return }
        for kind in [NSWindow.ButtonType.closeButton, .miniaturizeButton, .zoomButton] {
            window.standardWindowButton(kind)?.isHidden = trafficLightsHidden
        }
    }

    private var edgeTabListEnabled: Bool { (usesSidebar && !sidebarShown) || (!usesSidebar && frameless) }

    private var profileControl: some View {
        ProfileMenu(
            profileManager: profileManager,
            activeProfileId: sessionStore.activeProfileId,
            onSwitch: switchToProfile,
            onOpenInNewWindow: openProfileInNewWindow
        )
    }

    private var topChromeActions: TopChromeActions {
        TopChromeActions(
            activate: { switchToTab($0) },
            close: { closeTab($0) },
            newTab: { newTab() },
            reorder: { tabManager.moveTab(from: $0, to: $1) },
            submitAddress: { applyAddressBarSubmit() },
            goHome: { goHome() },
            toggleAI: { toggleAIPanel() },
            showDownloads: { showDownloadsHub = true },
            showHistory: { navigateToHistory() },
            askOnPage: { openAskOnPage() }
        )
    }

    private func topChrome(showsTabs: Bool) -> some View {
        TopChromeView(
            layout: layout,
            store: session.workspace,
            web: web,
            addressText: $addressBarText,
            addressFocused: $addressBarFocused,
            isFullScreen: isFullScreen,
            showsTabs: showsTabs,
            downloadsCount: downloadManager.recentDownloads.count,
            profileControl: AnyView(profileControl),
            extensions: session.extensions,
            actions: topChromeActions
        )
    }

    /// Web content, optionally inset in a rounded frame (Helium's "rounded frame").
    @ViewBuilder
    private var framedContent: some View {
        if roundedFrame {
            contentArea
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                .shadow(color: .black.opacity(0.18), radius: 1.5, y: 0.5)
                .padding(.top, showsTopChrome ? 0 : 8)
                .padding(.bottom, 8)
                .padding(.trailing, 8)
                .padding(.leading, sidebarShown ? 0 : 8)
        } else {
            contentArea
        }
    }

    /// Frameless mode: a thin hot zone at the top edge reveals the top bar.
    /// With the sidebar hidden there's no top bar: hovering the top edge brings
    /// back the window buttons until the pointer moves away.
    private var windowButtonsHotZone: some View {
        Color.clear
            .frame(height: 6)
            .frame(maxWidth: .infinity)
            .contentShape(Rectangle())
            .onHover { inside in
                guard inside, !windowButtonsPeeking else { return }
                windowButtonsPeeking = true
                watchPointerLeavingTop()
            }
    }

    private func watchPointerLeavingTop() {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
            guard windowButtonsPeeking, let window = hostWindow else { return }
            let point = window.mouseLocationOutsideOfEventStream
            let fromTop = (window.contentView?.bounds.height ?? 0) - point.y
            if fromTop > 44 || point.x < 0 || point.x > window.frame.width {
                windowButtonsPeeking = false
            } else {
                watchPointerLeavingTop()
            }
        }
    }

    @ViewBuilder
    private var topBarPeekOverlay: some View {
        if topBarPeeking {
            topChrome(showsTabs: false)
                .background(ZStack {
                    VisualEffectView(material: .titlebar, blendingMode: .withinWindow, state: .active)
                    activeProfile.profileColor.color.opacity(0.14)
                })
                .shadow(color: .black.opacity(0.2), radius: 8, y: 2)
                .onHover { inside in
                    if !inside && !addressBarFocused { topBarPeeking = false }
                }
                .transition(.move(edge: .top).combined(with: .opacity))
        } else {
            Color.clear
                .frame(height: 6)
                .frame(maxWidth: .infinity)
                .contentShape(Rectangle())
                .onHover { if $0 { topBarPeeking = true } }
        }
    }

    private func openAskOnPage() {
        guard !isCurrentTabStartOrAIChat else { return }
        if showBrowserFindBar {
            showBrowserFindBar = false
            browserFindQuery = ""
            if let id = tabManager.currentTab { web.clearFind(in: id) }
        }
        withAnimation(.spring(response: 0.3, dampingFraction: 0.85)) { askOnPageVisible = true }
    }

    /// Home: show the start page in the current tab.
    private func goHome() {
        guard let id = tabManager.currentTab else { return newTab() }
        web.removeWebView(for: id)
        tabManager.navigate(tab: id, to: URL(string: "about:blank")!)
        addressBarText = ""
    }

    private var sidebar: some View {
        SidebarView(
            store: session.workspace,
            web: web,
            addressText: $addressBarText,
            addressFocused: $addressBarFocused,
            isFullScreen: isFullScreen,
            actions: SidebarActions(
                activate: { switchToTab($0) },
                close: { closeTab($0) },
                newTab: { newTab() },
                store: session.workspace,
                tidyTitle: { session.tidyTitle($0) },
                tidyToday: { session.tidyToday() }
            ),
            onSubmitAddress: { applyAddressBarSubmit() },
            onToggleSidebar: toggleSidebar,
            onShowDownloads: { showDownloadsHub = true },
            extensions: session.extensions,
            profileControl: AnyView(profileControl)
        )
    }

    /// Hidden sidebar: a thin hot zone at the left edge reveals it over the content.
    @ViewBuilder
    private var sidebarPeekOverlay: some View {
        if sidebarPeeking {
            sidebar
                .frame(width: sidebarWidth)
                .frame(maxHeight: .infinity)
                .background(ZStack {
                    VisualEffectView(material: .sidebar, blendingMode: .withinWindow, state: .active)
                    activeProfile.profileColor.color.opacity(0.14)
                })
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                .shadow(color: .black.opacity(0.25), radius: 12, x: 2)
                .padding(.vertical, 6)
                .padding(.leading, 6)
                .onHover { inside in
                    if !inside && !addressBarFocused { sidebarPeeking = false }
                }
                .transition(.move(edge: .leading).combined(with: .opacity))
        } else {
            Color.clear
                .frame(width: 8)
                .frame(maxHeight: .infinity)
                .contentShape(Rectangle())
                .onHover { if $0 { sidebarPeeking = true } }
        }
    }

    private func toggleSidebar() {
        sidebarPeeking = false
        sidebarVisible.toggle()
    }

    @ViewBuilder
    private var contentArea: some View {
            // ─── Web content or start page ───────────────────────────
            if let currentId = tabManager.currentTab {
                let currentURL = tabManager.tabURL[currentId] ?? nil
                let isStartPage = (currentURL == nil || currentURL?.absoluteString == "about:blank")
                let isAIChat = currentURL?.scheme == "luma" && currentURL?.host == "ai"
                
                if isStartPage || isAIChat {
                    SmartSearchView(
                        gemini: gemini,
                        ollama: ollama,
                        tabManager: tabManager,
                        webViewWrapper: web,
                        tabId: currentId,
                        messages: aiChatMessagesBinding(for: currentId),
                        onNavigate: { url in navigateToURL(url) }
                    )
                    .id(currentId)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else if currentURL?.scheme == "luma", currentURL?.host == "history" {
                    // History page (always in its own tab)
                    // Special luma://history page
                    HistoryPageView(historyManager: historyManager, onSelectURL: { url in
                        navigateToURL(url)
                    })
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    ZStack(alignment: .top) {
                        WebViewContainer(webView: web.ensureWebView(for: currentId))
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                            .id(currentId)
                        if isFirstLoad {
                            ProgressView()
                                .scaleEffect(0.8)
                                .frame(maxWidth: .infinity, maxHeight: .infinity)
                                .onAppear {
                                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                                        isFirstLoad = false
                                    }
                                }
                        }
                        if web.googleSuspiciousErrorDetected, currentURL?.host?.contains("aistudio.google.com") == true {
                            GoogleSuspiciousErrorBanner(
                                onDismiss: { web.clearGoogleSuspiciousErrorBanner() },
                                onLearnMore: { showGoogleAPIKeyHelpSheet = true }
                            )
                            .padding(.horizontal, 12)
                            .padding(.top, 12)
                            .transition(.move(edge: .top).combined(with: .opacity))
                        }
                        if let preview = web.linkPreview, preview.tabId == currentId {
                            GeometryReader { geo in
                                let width: CGFloat = 320
                                let below = preview.rect.maxY + 8
                                let y = below + 160 < geo.size.height ? below : max(8, preview.rect.minY - 168)
                                LinkPreviewCard(url: preview.url, onOpen: {
                                    web.linkPreview = nil
                                    newTabWithURL(preview.url)
                                }, onClose: { web.linkPreview = nil })
                                .offset(x: min(max(8, preview.rect.minX), geo.size.width - width - 8), y: y)
                                .transition(.opacity)
                            }
                            .id(preview.url)
                        }
                        // Luna Passwords: fill / save offers for this tab.
                        VStack(alignment: .trailing, spacing: 8) {
                            if let offer = web.passwordSaveOffer, offer.tabId == currentId {
                                PasswordSaveCard(
                                    offer: offer,
                                    onSave: { username in
                                        try? PasswordVault.shared.save(host: offer.host, username: username,
                                                                       password: offer.password, profile: sessionStore.activeProfileId)
                                        web.passwordSaveOffer = nil
                                    },
                                    onNever: {
                                        PasswordVault.shared.setNeverSave(offer.host, true)
                                        web.passwordSaveOffer = nil
                                    },
                                    onDismiss: { web.passwordSaveOffer = nil }
                                )
                                .id(offer.host + offer.username)
                            } else if let offer = web.passwordFillOffer, offer.tabId == currentId {
                                PasswordFillCard(
                                    offer: offer,
                                    onFill: { cred in
                                        Task {
                                            if await web.fillPassword(cred, in: currentId) { web.passwordFillOffer = nil }
                                        }
                                    },
                                    onDismiss: { web.passwordFillOffer = nil }
                                )
                            }
                        }
                        .padding(.top, 12)
                        .padding(.trailing, 12)
                        .frame(maxWidth: .infinity, alignment: .trailing)
                        .transition(.move(edge: .top).combined(with: .opacity))
                        .animation(.spring(response: 0.3, dampingFraction: 0.85), value: web.passwordFillOffer)
                        .animation(.spring(response: 0.3, dampingFraction: 0.85), value: web.passwordSaveOffer)
                        if askOnPageVisible {
                            AskOnPageBar(tabId: currentId, web: web, onClose: { askOnPageVisible = false })
                                .padding(.top, 12)
                                .padding(.trailing, 12)
                                .frame(maxWidth: .infinity, alignment: .trailing)
                                .transition(.move(edge: .top).combined(with: .opacity))
                                .id(currentId)
                        }
                        if showBrowserFindBar {
                            BrowserFindBar(
                                query: $browserFindQuery,
                                onFind: { query in
                                    if let id = tabManager.currentTab {
                                        web.findInPage(query: query, in: id)
                                    }
                                },
                                onNext: {
                                    if let id = tabManager.currentTab {
                                        web.findNext(in: id)
                                    }
                                },
                                onPrevious: {
                                    if let id = tabManager.currentTab {
                                        web.findPrevious(in: id)
                                    }
                                },
                                onDismiss: {
                                    showBrowserFindBar = false
                                    browserFindQuery = ""
                                    if let id = tabManager.currentTab {
                                        web.clearFind(in: id)
                                    }
                                }
                            )
                            .transition(.move(edge: .top).combined(with: .opacity))
                        }
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .onDrop(of: [.url, .fileURL, .plainText], isTargeted: nil) { providers in
                        handleURLDrop(providers: providers, action: { navigateToURL($0) })
                    }
                    .sheet(isPresented: $showGoogleAPIKeyHelpSheet) {
                        GoogleAPIKeyHelpView()
                    }
                }
            } else {
                Color(nsColor: .windowBackgroundColor)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .overlay(Text("No tab").foregroundColor(.secondary))
            }
    }

    /// Address suggestions, placed under whichever address field is on screen.
    @ViewBuilder
    private func suggestionsOverlay(anchor: Anchor<CGRect>?) -> some View {
        let hasSuggestions = !historySuggestions.isEmpty || !searchSuggestions.isEmpty
        if let anchor, addressBarFocused,
           !addressBarText.trimmingCharacters(in: .whitespaces).isEmpty,
           hasSuggestions {
            GeometryReader { proxy in
                let field = proxy[anchor]
                AddressBarSuggestionsList(
                    historyItems: historySuggestions,
                    searchPhrases: Array(searchSuggestions.prefix(5)),
                    selectedIndex: addressBarKeyState.selectedIndex,
                    onSelectHistory: { url in
                        searchSuggestions = []
                        historySuggestions = []
                        addressBarKeyState.visible = false
                        navigateToURL(url)
                    },
                    onSelectSearch: { phrase in
                        addressBarText = phrase
                        searchSuggestions = []
                        historySuggestions = []
                        addressBarKeyState.visible = false
                        navigateFromAddressBar()
                    }
                )
                .background(.regularMaterial)
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                .shadow(color: .black.opacity(0.18), radius: 10, y: 4)
                .frame(width: max(field.width, 440))
                .offset(x: field.minX, y: field.maxY + 6)
                .onAppear {
                    addressBarKeyState.visible = true
                    addressBarKeyState.totalCount = historySuggestions.count + searchSuggestions.count
                    addressBarKeyState.selectedIndex = 0
                }
                .onDisappear { addressBarKeyState.visible = false }
            }
        }
    }

    // MARK: - Profile switching

    /// Two-finger horizontal swipe over the sidebar or top bar moves to the
    /// next/previous profile. Returns true when the event was used.
    private func handleProfileSwipe(_ event: NSEvent) -> Bool {
        guard let window = hostWindow, event.window === window, event.hasPreciseScrollingDeltas,
              profileManager.profiles.count > 1 else { return false }
        if event.phase == .began {
            swipeTravel = 0
            swipeConsumed = false
        }
        guard event.phase == .began || event.phase == .changed else {
            if event.phase == .ended || event.phase == .cancelled { swipeTravel = 0 }
            return false
        }
        // Only over the chrome: the sidebar, or the top bar rows.
        let point = event.locationInWindow
        let fromTop = (window.contentView?.bounds.height ?? 0) - point.y
        let overChrome = (sidebarShown && point.x <= sidebarWidth)
            || (showsTopChrome && fromTop <= TopChromeView.height(for: layout, showsTabs: !frameless))
        guard overChrome, abs(event.scrollingDeltaX) > abs(event.scrollingDeltaY) * 1.5 || swipeTravel != 0 else { return false }
        guard !swipeConsumed else { return true }
        swipeTravel += event.scrollingDeltaX
        if abs(swipeTravel) > 90 {
            swipeConsumed = true
            let offset = swipeTravel < 0 ? 1 : -1
            if let next = profileManager.neighbor(of: sessionStore.activeProfileId, offset: offset) {
                switchToProfile(next)
                showProfileToast(next)
            }
        }
        return true
    }

    private func showProfileToast(_ profile: BrowserProfile) {
        withAnimation(.spring(response: 0.3, dampingFraction: 0.85)) { profileToast = profile }
        let id = profile.id
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
            guard profileToast?.id == id else { return }
            withAnimation(.easeOut(duration: 0.25)) { profileToast = nil }
        }
    }

    private func switchToProfile(_ profile: BrowserProfile) {
        guard profile.id != sessionStore.activeProfileId else { return }
        sessionStore.switchTo(profileId: profile.id)

        // Reset address bar
        addressBarText = ""
        searchSuggestions = []
        historySuggestions = []
        tabsWithPanelOpen = []
        syncAddressBarFromCurrentTab()
    }

    private func openProfileInNewWindow(_ profile: BrowserProfile) {
        let newWindow = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 1200, height: 800),
            styleMask: [.titled, .closable, .miniaturizable, .resizable, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )
        // Programmatic NSWindows default to isReleasedWhenClosed = true, which crashes
        // under ARC when the window closes. Keep a strong reference until it closes instead.
        newWindow.isReleasedWhenClosed = false
        newWindow.titlebarAppearsTransparent = true
        newWindow.titleVisibility = .hidden
        newWindow.styleMask.insert(.fullSizeContentView)
        newWindow.isMovableByWindowBackground = false
        newWindow.tabbingMode = .disallowed
        newWindow.center()
        newWindow.title = "\(profile.name) — Luna"

        let shellView = BrowserShellView(initialProfileId: profile.id)
        newWindow.contentView = NSHostingView(rootView: shellView)
        ProfileWindowRegistry.shared.retain(newWindow)
        newWindow.makeKeyAndOrderFront(nil)
    }

    // MARK: - Helpers

    private func syncAddressBarFromCurrentTab() {
        if let id = tabManager.currentTab {
            if let url = web.currentURL {
                tabManager.navigate(tab: id, to: url)
                let hide = url.absoluteString == "about:blank" || (url.scheme == "luma" && url.host == "ai")
                addressBarText = hide ? "" : url.absoluteString
            } else if let url = tabManager.tabURL[id] ?? nil {
                let hide = url.absoluteString == "about:blank" || (url.scheme == "luma" && url.host == "ai")
                addressBarText = hide ? "" : url.absoluteString
            } else {
                addressBarText = ""
            }
        } else {
            addressBarText = ""
        }
    }

    /// Selects the entire address bar contents when the user clicks/taps into it.
    /// Uses the current first responder (NSTextView) in the key window.
    private func selectAllAddressBarText() {
        DispatchQueue.main.async {
            if let editor = NSApp.keyWindow?.firstResponder as? NSTextView {
                editor.selectAll(nil)
            }
        }
    }

    private func fetchHistorySuggestions(for query: String) {
        historyDebounceTask?.cancel()
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count >= 2 else {
            historySuggestions = []
            return
        }
        let task = DispatchWorkItem { [trimmed] in
            let results = historyManager.urlAutocompleteSuggestions(prefix: trimmed, limit: 5)
            self.historySuggestions = results
        }
        historyDebounceTask = task
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05, execute: task)
    }

    private func fetchSearchSuggestions(for query: String) {
        suggestionDebounceTask?.cancel()
        guard searchSuggestionsEnabled else {
            searchSuggestions = []
            return
        }
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count >= 2 else {
            searchSuggestions = []
            return
        }
        let task = DispatchWorkItem { [trimmed] in
            guard let encoded = trimmed.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
                  let url = URL(string: "https://suggestqueries.google.com/complete/search?client=firefox&q=\(encoded)") else { return }
            var request = URLRequest(url: url)
            request.timeoutInterval = 3
            URLSession.shared.dataTask(with: request) { data, _, _ in
                guard let data = data,
                      var raw = String(data: data, encoding: .utf8) else {
                    DispatchQueue.main.async { self.searchSuggestions = [] }
                    return
                }
                if raw.hasPrefix("window."), let start = raw.firstIndex(of: "["), let end = raw.lastIndex(of: "]") {
                    raw = String(raw[start...end])
                }
                guard let jsonData = raw.data(using: .utf8),
                      let json = try? JSONSerialization.jsonObject(with: jsonData) as? [Any],
                      json.count >= 2,
                      let rawSuggestions = json[1] as? [Any] else {
                    DispatchQueue.main.async { self.searchSuggestions = [] }
                    return
                }
                let phrases = rawSuggestions.compactMap { item -> String? in
                    if let s = item as? String { return s }
                    if let arr = item as? [Any], let first = arr.first as? String { return first }
                    return nil
                }
                DispatchQueue.main.async {
                    // Drop stale responses: only apply if the user is still typing this query.
                    guard self.addressBarText.trimmingCharacters(in: .whitespacesAndNewlines) == trimmed else { return }
                    self.searchSuggestions = Array(phrases.prefix(5))
                }
            }.resume()
        }
        suggestionDebounceTask = task
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18, execute: task)
    }

    private func resolveToURL(_ input: String) -> URL? {
        let trimmed = input.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        
        // Handle luma:// scheme
        if trimmed.lowercased().hasPrefix("luma://") {
            return URL(string: trimmed)
        }
        // Handle file:// so we don't turn it into https://file:///...
        if trimmed.lowercased().hasPrefix("file://") {
            return URL(string: trimmed)
        }
        if trimmed.lowercased().hasPrefix("http://") || trimmed.lowercased().hasPrefix("https://") {
            return URL(string: trimmed)
        }
        if !trimmed.contains(" "), trimmed.contains(".") {
            return URL(string: "https://" + trimmed)
        }
        let encoded = trimmed.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? trimmed
        return URL(string: "https://www.google.com/search?q=" + encoded)
    }

    /// Submit address bar: if first history suggestion matches typed prefix, go there; else resolve as URL or search.
    private func applyAddressBarSubmit() {
        let trimmed = addressBarText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if !trimmed.isEmpty,
           let first = historySuggestions.first,
           first.display.lowercased().hasPrefix(trimmed)
            || first.url.absoluteString.lowercased().contains(trimmed)
            || (first.url.host?.lowercased().contains(trimmed) ?? false) {
            searchSuggestions = []
            historySuggestions = []
            addressBarKeyState.visible = false
            navigateToURL(first.url)
            return
        }
        searchSuggestions = []
        historySuggestions = []
        addressBarKeyState.visible = false
        navigateFromAddressBar()
    }

    /// Apply the currently selected suggestion (keyboard Enter): navigate to URL or run search.
    private func applySelectionAtIndex(_ index: Int) {
        let h = historySuggestions.count
        let total = h + searchSuggestions.count
        guard index >= 0, index < total else { return }
        if index < h {
            let url = historySuggestions[index].url
            searchSuggestions = []
            historySuggestions = []
            addressBarKeyState.visible = false
            navigateToURL(url)
        } else {
            let phrase = searchSuggestions[index - h]
            searchSuggestions = []
            historySuggestions = []
            addressBarKeyState.visible = false
            addressBarText = phrase
            navigateFromAddressBar()
        }
    }

    private func navigateFromAddressBar() {
        guard let url = resolveToURL(addressBarText) else { return }
        navigateToURL(url)
    }
    
    private func navigateToHistory() {
        // Always open History in a new tab
        if let url = URL(string: "luma://history") {
            let id = tabManager.newTab(url: url)
            web.setActiveTab(id)
            addressBarText = url.absoluteString
            isFirstLoad = false
            return
        }
    }

    private func navigateToURL(_ url: URL) {
        // Handle luma:// scheme
        if url.scheme == "luma" {
            if url.host == "history" {
                let id = tabManager.newTab(url: url)
                web.setActiveTab(id)
                addressBarText = url.absoluteString
                isFirstLoad = false
                return
            }
            if url.host == "ai" {
                return
            }
        }
        
        if tabManager.currentTab == nil {
            let id = tabManager.newTab(url: url)
            _ = web.ensureWebView(for: id)
            web.setActiveTab(id)
            web.load(url: url, in: id)
        } else if let id = tabManager.currentTab {
            tabManager.navigate(tab: id, to: url)
            web.load(url: url, in: id)
        }
        addressBarText = url.absoluteString
    }

    private func newTabWithURL(_ url: URL) {
        let id = tabManager.newTab(url: url)
        _ = web.ensureWebView(for: id)
        web.setActiveTab(id)
        web.load(url: url, in: id)
        tabManager.navigate(tab: id, to: url)
        addressBarText = url.absoluteString
    }

    private func handleURLDrop(providers: [NSItemProvider], action: @escaping (URL) -> Void) -> Bool {
        guard let provider = providers.first else { return false }
        if provider.hasItemConformingToTypeIdentifier(UTType.url.identifier) {
            _ = provider.loadObject(ofClass: URL.self) { url, _ in
                if let u = url, (u.scheme == "http" || u.scheme == "https" || u.scheme == "file") {
                    DispatchQueue.main.async { action(u) }
                }
            }
        } else if provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
            _ = provider.loadObject(ofClass: URL.self) { url, _ in
                if let u = url {
                    DispatchQueue.main.async { action(u) }
                }
            }
        } else if provider.hasItemConformingToTypeIdentifier(UTType.plainText.identifier) {
            _ = provider.loadObject(ofClass: String.self) { str, _ in
                if let s = str?.trimmingCharacters(in: .whitespacesAndNewlines),
                   let u = URL(string: s),
                   u.scheme == "http" || u.scheme == "https" {
                    DispatchQueue.main.async { action(u) }
                }
            }
        }
        return true
    }

    private func aiChatMessagesBinding(for tabId: UUID) -> Binding<[ChatMessage]> {
        Binding(
            get: { session.chatStore.messages(for: tabId) },
            set: { session.chatStore.setMessages($0, for: tabId) }
        )
    }

    private var isCurrentTabStartOrAIChat: Bool {
        guard let id = tabManager.currentTab,
              let url = tabManager.tabURL[id] ?? nil else { return true }
        if url.absoluteString == "about:blank" { return true }
        if url.scheme == "luma" && url.host == "ai" { return true }
        return false
    }

    private func toggleAIPanel() {
        guard let id = tabManager.currentTab else { return }
        guard !isCurrentTabStartOrAIChat else { return }
        if tabsWithPanelOpen.contains(id) {
            tabsWithPanelOpen.remove(id)
        } else {
            shouldResetPanelWidth = true
            tabsWithPanelOpen.insert(id)
        }
    }

    private func newTab() {
        let id = tabManager.newTab(url: nil)
        _ = web.ensureWebView(for: id)
        web.setActiveTab(id)
        web.load(url: URL(string: "about:blank")!, in: id)
        addressBarText = ""
        // Cmd+T opens the AI start page, which focuses its own input.
        addressBarFocused = false
    }

    private func closeCurrentTab() {
        guard let id = tabManager.currentTab else { return }
        // Safari-like: Cmd+W on the last remaining tab, when it's already an empty
        // start page, closes the window instead of endlessly respawning new tabs.
        let url = tabManager.tabURL[id] ?? nil
        let isEmptyStartPage = (url == nil || url?.absoluteString == "about:blank")
        if tabManager.tabCount() == 1, isEmptyStartPage {
            hostWindow?.performClose(nil)
            return
        }
        closeTab(id)
    }

    /// Heartbeat animation on downloads icon: pulse 25% bigger twice (1 → 1.25 → 1 → 1.25 → 1).
    private func runDownloadsHeartbeat() {
        let step: TimeInterval = 0.12
        withAnimation(.easeInOut(duration: step)) { downloadIconScale = 1.25 }
        DispatchQueue.main.asyncAfter(deadline: .now() + step) {
            withAnimation(.easeInOut(duration: step)) { downloadIconScale = 1 }
            DispatchQueue.main.asyncAfter(deadline: .now() + step) {
                withAnimation(.easeInOut(duration: step)) { downloadIconScale = 1.25 }
                DispatchQueue.main.asyncAfter(deadline: .now() + step) {
                    withAnimation(.easeInOut(duration: step)) { downloadIconScale = 1 }
                }
            }
        }
    }

    private func closeTab(_ id: UUID) {
        web.removeWebView(for: id)
        tabsWithPanelOpen.remove(id)
        session.chatStore.removeMessages(for: id)
        tabManager.closeTab(id)
        if tabManager.currentTab == nil {
            newTab()
        } else if let newCurrent = tabManager.currentTab {
            web.setActiveTab(newCurrent)
            syncAddressBarFromCurrentTab()
        }
    }

    private func switchToTab(_ id: UUID) {
        tabManager.switchToTab(id)
        web.setActiveTab(id)
        syncAddressBarFromCurrentTab()
    }

    private func executePendingAction() {
        guard let action = pendingAction else { return }
        let tabToClose: UUID?
        if action.type == .close_tab {
            if let raw = action.payload?["index"], let index = Int(raw), index >= 1, index <= tabManager.tabCount() {
                tabToClose = tabManager.tabOrder[index - 1]
            } else {
                tabToClose = tabManager.currentTab
            }
        } else {
            tabToClose = nil
        }
        let result = router.execute(action: action, tabManager: tabManager)
        switch result {
        case .success:
            if let id = tabToClose {
                web.removeWebView(for: id)
                tabsWithPanelOpen.remove(id)
                session.chatStore.removeMessages(for: id)
            }
            if action.type == .new_tab || action.type == .navigate,
               let urlString = action.payload?["url"],
               let url = URL(string: urlString.contains("://") ? urlString : "https://" + urlString) {
                if action.type == .new_tab, let id = tabManager.currentTab {
                    web.setActiveTab(id)
                    web.load(url: url, in: id)
                    tabManager.navigate(tab: id, to: url)
                    addressBarText = url.absoluteString
                } else if action.type == .navigate, let id = tabManager.currentTab {
                    web.load(url: url, in: id)
                    tabManager.navigateCurrentTab(to: url)
                    addressBarText = url.absoluteString
                }
            }
            if action.type == .switch_tab, let id = tabManager.currentTab {
                web.setActiveTab(id)
                syncAddressBarFromCurrentTab()
            }
            if action.type == .close_tab {
                if tabManager.currentTab == nil {
                    newTab()
                } else if let id = tabManager.currentTab {
                    web.setActiveTab(id)
                    syncAddressBarFromCurrentTab()
                }
            }
        case .failure:
            break
        }
        pendingAction = nil
    }
    
}

// MARK: - Profile window registry

/// Keeps profile windows alive (isReleasedWhenClosed = false) and releases them on close.
final class ProfileWindowRegistry {
    static let shared = ProfileWindowRegistry()
    private var windows: Set<NSWindow> = []
    private init() {}

    func retain(_ window: NSWindow) {
        windows.insert(window)
        NotificationCenter.default.addObserver(
            forName: NSWindow.willCloseNotification, object: window, queue: .main
        ) { [weak self] note in
            guard let closed = note.object as? NSWindow else { return }
            self?.windows.remove(closed)
        }
    }
}

// MARK: - Downloads hub (recent downloads; open / reveal in Finder)

private struct DownloadsHubView: View {
    @ObservedObject private var downloadManager = DownloadManager.shared
    @Environment(\.dismiss) private var dismiss

    private static let dateFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateStyle = .short
        f.timeStyle = .short
        return f
    }()

    var body: some View {
        VStack(spacing: 0) {
            HStack {
                Image(systemName: "arrow.down.circle")
                    .font(.system(size: 18, weight: .medium))
                Text("Downloads")
                    .font(.system(size: 18, weight: .semibold))
                Spacer()
                Button("Done") { dismiss() }
                    .buttonStyle(.borderedProminent)
            }
            .padding(.horizontal, 20)
            .padding(.vertical, 14)

            if downloadManager.recentDownloads.isEmpty {
                VStack(spacing: 12) {
                    Image(systemName: "tray.and.arrow.down")
                        .font(.system(size: 40))
                        .foregroundStyle(.secondary)
                    Text("No recent downloads")
                        .font(.system(size: 14, weight: .medium))
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                List {
                    ForEach(downloadManager.recentDownloads) { item in
                        HStack(spacing: 12) {
                            Image(systemName: "doc.fill")
                                .font(.system(size: 20))
                                .foregroundStyle(.secondary)
                            VStack(alignment: .leading, spacing: 2) {
                                Text(item.displayName)
                                    .font(.system(size: 13, weight: .medium))
                                    .lineLimit(1)
                                    .truncationMode(.middle)
                                HStack(spacing: 6) {
                                    Text(Self.dateFormatter.string(from: item.date))
                                    if item.isTidying {
                                        Text("· Tidying name…")
                                    } else if let original = item.originalFileURL {
                                        Text("· Renamed from \(original.lastPathComponent)").lineLimit(1).truncationMode(.middle)
                                        Button("Undo") { downloadManager.undoTidy(item.id) }
                                            .buttonStyle(.link)
                                    }
                                }
                                .font(.system(size: 11))
                                .foregroundStyle(.secondary)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            if item.originalFileURL == nil, !item.isTidying {
                                Button {
                                    downloadManager.tidy(item.id)
                                } label: {
                                    Image(systemName: "sparkles")
                                }
                                .buttonStyle(.borderless)
                                .help("Tidy file name")
                            }
                            Button("Open") {
                                downloadManager.open(item)
                            }
                            .buttonStyle(.bordered)
                            Button("Show in Finder") {
                                downloadManager.revealInFinder(item)
                            }
                            .buttonStyle(.bordered)
                            Button(role: .destructive) {
                                downloadManager.removeItem(item)
                            } label: {
                                Image(systemName: "trash")
                                    .font(.system(size: 12, weight: .medium))
                            }
                            .buttonStyle(.plain)
                            .help("Remove from list")
                        }
                        .padding(.vertical, 4)
                    }
                }
                .listStyle(.plain)
            }
        }
        .frame(minWidth: 480, minHeight: 320)
    }
}

